#!/usr/bin/env python3
"""NOX WEB29 3A V06 source-only patch generator. Never deploys or contacts OneHost."""
import argparse
import base64
import gzip
import hashlib
from pathlib import Path

B64 = ""
PATCH_SHA256 = "deab7398e666599a0dded8ee1b45710607deab15a524946832513e95bdbbb8ef"
PREIMAGE_JS_SHA256 = "c12a85540ae0f715f0e6669771d6331ff49f58e4c61331c9df7ab348afb6dadc"
POSTIMAGE_JS_SHA256 = "8bb1e07e8e5e5fdd573af5f4e0e6e56bfb035f39b007cfd014bcc52e2c6731b1"
TARGET = "site/pc/v25/nox-shell-v25.js"

def patch_bytes():
    raw = gzip.decompress(base64.b64decode(B64, validate=True))
    if hashlib.sha256(raw).hexdigest() != PATCH_SHA256:
        raise ValueError("HOLD_PATCH_HASH_MISMATCH")
    return raw

def main():
    parser = argparse.ArgumentParser(description="Write SHA-pinned source patch, not a live deployment")
    parser.add_argument("--output", type=Path, required=True, help="Destination .patch")
    args = parser.parse_args()
    patch = patch_bytes()
    args.output.write_bytes(patch)
    print("SOURCE_PATCH_VERIFIED", TARGET, PATCH_SHA256, len(patch))
    print("APPLY_ONLY_TO_STAGING_PREIMAGE", PREIMAGE_JS_SHA256)
    print("EXPECTED_POSTIMAGE", POSTIMAGE_JS_SHA256)
    print("NATIVE_DEPLOYMENT_HOLD: owner writer lease, exact live preimage and rollback required")

if __name__ == "__main__":
    main()
